-- U: START TRANSACTION; UPDATE unrelated SET value=8 WHERE id=1;
-- D (separate connection, blocks): ALTER TABLE tasks ADD COLUMN note INT NOT NULL DEFAULT 0;
-- R (separate connection, also queues): SELECT id,payload FROM tasks ORDER BY id;
-- Run diagnose.sql using an observer; run release.sql on A, not D/U/R.

