 execute(admin,'CREATE TABLE quarantined(id INT NOT NULL,revision INT NOT NULL,doc JSON NULL,PRIMARY KEY(id,revision)) ENGINE=InnoDB')
 off=secrets.randbelow(900)+100
 good=lambda enabled=True,timeout=100:{'version':1,'enabled':enabled,'timeout_ms':timeout}
