 def payload(doc):return None if doc is None else ('null' if doc=='JSON_NULL' else json.dumps(doc,separators=(',',':')))
 for i,rev,doc in initial:execute(admin,'INSERT INTO configs VALUES(%s,%s,%s)',(off+i,rev,payload(doc)))
 for i,rev,doc in [(2,1,good(True,200)),(3,2,good(False,300)),(6,2,good(True,100)),(1,1,good(False,999))]:execute(admin,'INSERT INTO approved_patches VALUES(%s,%s,%s)',(off+i,rev,payload(doc)))
 client=learner('SELECT,INSERT,UPDATE,DELETE,ALTER,TRIGGER')
 def run(name):return execute(client,pathlib.Path(name).read_text())
 def rows(table):return execute(admin,'SELECT * FROM '+table+' ORDER BY id')
 invalids=[None,'JSON_NULL',{},[],{'version':1,'enabled':1,'timeout_ms':100},{'version':1,'enabled':None,'timeout_ms':100},{'version':1,'enabled':True,'timeout_ms':'100'},{'version':1,'enabled':True,'timeout_ms':150.5},good(True,99),good(True,5001),{'version':2,'enabled':True,'timeout_ms':100},{'version':1,'enabled':True,'timeout_ms':100,'extra':0}]
 def rejection_cases(expected_codes):
  before=rows('configs')
  for n,doc in enumerate(invalids):
   try:execute(client,'INSERT INTO configs VALUES(%s,1,%s)',(off+100+n,payload(doc)))
   except pymysql.Error as exc:assert exc.args[0] in expected_codes,exc
   else:raise AssertionError('invalid new config accepted: '+repr(doc))
   try:execute(client,'UPDATE configs SET doc=%s WHERE id=%s',(payload(doc),off+1))
   except pymysql.Error as exc:assert exc.args[0] in expected_codes,exc
   else:raise AssertionError('invalid update accepted: '+repr(doc))
  assert rows('configs')==before
