class RedisError(Exception):pass
class Client:
    def __init__(self,path):
        self.sock=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM);self.sock.settimeout(3)
        self.sock.connect(str(path));self.file=self.sock.makefile('rb');self.calls=[]
    def close(self):self.file.close();self.sock.close()
    def _read(self):
        line=self.file.readline()
        if not line.endswith(b'\r\n'):raise EOFError('truncated RESP')
        k,v=line[:1],line[1:-2]
        if k==b'+':return v
        if k==b'-':return RedisError(v.decode('utf8',errors='replace'))
