      'publish_own':['PUBLISH',channel,'body'],'publish_foreign':['PUBLISH','foreign:'+channel,'body'],
      'subscribe_own':['SUBSCRIBE',channel],'psubscribe_foreign':['PSUBSCRIBE','foreign:'+row['channel_prefix']+'*'],
      'configure':['CONFIG','GET','maxmemory'],'script':['EVAL','return 1',0],
