def repair(client,target_limit,key,value,ttl_seconds):
    if type(target_limit) is not int or not 0<target_limit<=8*1024*1024:
        raise ValueError('authorized capacity exceeded')
    if type(ttl_seconds) is not int or ttl_seconds<=0:raise ValueError('positive integer TTL required')
    fields={}
    for line in client.execute('INFO','memory').splitlines():
        if b':' in line:
            k,v=line.split(b':',1);fields[k]=v
    used=int(fields[b'used_memory'])
    before=int(client.execute('CONFIG','GET','maxmemory')[1])
    policy=client.execute('CONFIG','GET','maxmemory-policy')[1]
    if policy!=b'volatile-lru' or target_limit<=used:raise ValueError('unsafe capacity or unexpected policy')
    client.execute('CONFIG','SET','maxmemory',target_limit)
    client.execute('SET',key,value,'EX',ttl_seconds)
    return {'policy':policy.decode('ascii'),'before_limit':before,
            'after_limit':int(client.execute('CONFIG','GET','maxmemory')[1]),
            'value':client.execute('GET',key),'ttl_seconds':client.execute('TTL',key)}
