import hashlib
def invoke(client,script,keys,args,max_reloads=1):
    if type(max_reloads) is not int or not 0<=max_reloads<=3:raise ValueError('0..3 reloads required')
    digest=hashlib.sha1(script).hexdigest()
    for attempt in range(max_reloads+1):
        try:return client.execute('EVALSHA',digest,len(keys),*keys,*args)
        except client.Error as error:
